<?php if(!$market){echo '<p>Mercado não encontrado</p>'; return;} ?><h2><?= htmlspecialchars($market['question']) ?></h2><p>Status: <?= htmlspecialchars($market['status']) ?></p><?php foreach($market['options'] as $o): ?><div class='prediction-option <?= (int)($market['resolved_option_id']??0)===(int)$o['id']?'winner':'' ?>'><?= htmlspecialchars($o['label']) ?> - <?= number_format(((float)$o['probability_value']*100),2,',','.') ?>%</div><?php endforeach; ?><h3>Apostas recentes</h3><?php foreach($market['bets'] as $b): ?><div><?= htmlspecialchars($b['team_name']) ?>: R$ <?= number_format((float)$b['amount'],2,',','.') ?> em <?= htmlspecialchars($b['option_label']) ?></div><?php endforeach; ?><?php if(in_array($market['status'],['open','closed'],true)): ?><form method='post' action='/liquidity/predictions/<?= (int)$market['id'] ?>/resolve'><?= \App\Core\Csrf::input() ?><select name='winning_option_id'><?php foreach($market['options'] as $o): ?><option value='<?= (int)$o['id'] ?>'><?= htmlspecialchars($o['label']) ?></option><?php endforeach; ?></select><textarea name='resolution_notes' placeholder='Notas'></textarea><button>Resolver</button></form><?php endif; ?>
